{
  "title": "The Gilded Ruin",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined city.",
      "visual_description": "A group of four figures stands on a hill overlooking a shattered royal city, its towers silhouetted against a blood-red sunset.",
      "characters": ["Eira", "Kael", "Maren", "Torben"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople gather at the main gate.",
      "visual_description": "A crowd of ragged townspeople huddles near the broken city gates, clutching bundles and staring in fear at the shadows beyond.",
      "characters": ["Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "An armored patrol blocks the entrance.",
      "visual_description": "Three soldiers in crested helms and dented breastplates stand with spears crossed before the iron portcullis, torchlight flickering on their armor.",
      "characters": ["Guard Captain", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 4,
      "caption": "The party bribes or fights past the guards.",
      "visual_description": "Eira tosses a coin pouch to the ground while Kael's hand rests on his sword hilt, the guards exchanging tense glances.",
      "characters": ["Eira", "Kael", "Guard Captain", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 5,
      "caption": "Inside, old royal banners hang torn from the walls.",
      "visual_description": "Long crimson banners with faded golden crests droop from cracked stone walls along a debris-littered avenue.",
      "characters": ["Eira", "Kael", "Maren", "Torben"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon reach the party from a refugee.",
      "visual_description": "A gaunt old woman clutches a child's hand and whispers urgently to Maren, her eyes wide with terror.",
      "characters": ["Maren", "Refugee Woman", "Child"]
    },
    {
      "scene_number": 7,
      "caption": "They discover a cursed tower that twists the mind.",
      "visual_description": "A spiral staircase of black stone rises into darkness, with faint runes glowing like eyes along the walls.",
      "characters": ["Eira", "Kael", "Maren", "Torben"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door puzzles the group.",
      "visual_description": "A massive door of carved obsidian, inlaid with silver constellations that slowly rotate, blocks their path.",
      "characters": ["Eira", "Kael", "Maren", "Torben"]
    },
    {
      "scene_number": 9,
      "caption": "Torben solves the door's riddle.",
      "visual_description": "Torben presses a sequence of stars on the door with his fingertips, and the stone grinds inward.",
      "characters": ["Torben", "Eira", "Kael", "Maren"]
    },
    {
      "scene_number": 10,
      "caption": "Inside, they find the prisoner in a crystal cell.",
      "visual_description": "A young woman with silver hair floats asleep inside a hexagonal crystal suspended from chains in a high chamber.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira"]
    },
    {
      "scene_number": 11,
      "caption": "The rescue triggers a magical alarm.",
      "visual_description": "Shimmering blue shockwaves erupt from the crystal's pedestal, ringing like a bell through the tower.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols converge on the tower.",
      "visual_description": "Soldiers in black-and-gold armor pour into the courtyard below, torches bobbing as they form ranks.",
      "characters": ["Guard Captain", "Soldier 1", "Soldier 2", "Soldier 3", "Soldier 4"]
    },
    {
      "scene_number": 13,
      "caption": "The party fights through the courtyard.",
      "visual_description": "Kael deflects a sword strike while Eira fires an arrow past his shoulder, sparks flying from the clashing blades.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira", "Guard Captain", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 14,
      "caption": "A dragon's roar echoes from the castle.",
      "visual_description": "A massive winged shadow passes over the moon, and a reptilian bellow shakes loose tiles from the rooftops.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira"]
    },
    {
      "scene_number": 15,
      "caption": "They flee through a crumbling market district.",
      "visual_description": "The party sprints between collapsed stalls and toppled statues, with dust and cobwebs filling the air.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira"]
    },
    {
      "scene_number": 16,
      "caption": "The escape bridge is partially destroyed.",
      "visual_description": "A stone bridge arches over a deep chasm, its middle section broken into a gap of splintered masonry and dangling ropes.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira"]
    },
    {
      "scene_number": 17,
      "caption": "The party crosses under fire from the patrols.",
      "visual_description": "Arrows whistle past as Torben carries Lira across a narrow wooden plank, with Kael shielding them with a raised shield.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira", "Guard Captain", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "The party reaches safety as the bridge's remaining supports shatter, sending stone and soldiers tumbling into the abyss below.",
      "characters": ["Eira", "Kael", "Maren", "Torben", "Lira"]
    }
  ]
}

